<?php
namespace App\Domain\ServiceOrders;use App\Enums\ServiceOrderStatus;use DomainException;
class ServiceOrderStatusTransition{const MAP=[ServiceOrderStatus::NEW=>[ServiceOrderStatus::CONFIRMED,ServiceOrderStatus::ASSIGNED,ServiceOrderStatus::CANCELLED],ServiceOrderStatus::CONFIRMED=>[ServiceOrderStatus::ASSIGNED,ServiceOrderStatus::CANCELLED],ServiceOrderStatus::ASSIGNED=>[ServiceOrderStatus::ON_THE_WAY,ServiceOrderStatus::IN_PROGRESS,ServiceOrderStatus::CANCELLED],ServiceOrderStatus::ON_THE_WAY=>[ServiceOrderStatus::IN_PROGRESS,ServiceOrderStatus::CANCELLED],ServiceOrderStatus::IN_PROGRESS=>[ServiceOrderStatus::COMPLETED,ServiceOrderStatus::CANCELLED],ServiceOrderStatus::COMPLETED=>[],ServiceOrderStatus::CANCELLED=>[]];public function assertAllowed(string $from,string $to):void{if(!in_array($to,self::MAP[$from]??[],true))throw new DomainException("Invalid service order transition: {$from} -> {$to}");}}
